// Collect the topics of column "topic" into one list (one Actor run for the whole sheet, up to 500 topics).
const seedKeywords = $input.all()
  .map((item) => String(item.json.topic ?? '').trim())
  .filter(Boolean);
if (seedKeywords.length === 0) throw new Error('No topic found: add a column named "topic" to the Topics tab.');
return [{ json: { seedKeywords } }];

// One row per question, ready for an FAQ section or a content brief.
return $input.all()
  .map((i) => i.json)
  .filter((r) => r.found !== false && r.text)
  .map((r) => ({
    json: {
      topic: r.seed,
      question: r.text,
      type: r.type,
      position: r.position,
      openedFrom: r.parentQuestion ?? '',
      answer: r.answer ?? '',
      sourceUrl: r.sourceUrl ?? '',
      country: r.country,
      checkedAt: r.observedAt,
    },
  }));
